from pathlib import Path
import base64,json
R=Path(__file__).resolve().parents[2];O=R/'renders/ledian_dojo_v1';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={e['id']:{**e,'images':{n:uri(O/e['id']/(n+'.png')) for n in e['layers']},'schema':uri(O/e['id']/'schema.png')} for e in m['rooms']}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ledian · couloirs et salles</title><style>*{box-sizing:border-box}body{margin:0;background:#191815;color:#e2d9bf;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#c6bea8;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#d2b87c}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #8a785a;border-radius:6px;background:#3f392b;color:#f7eedc}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#171716}aside{background:#27251e;padding:18px;border-radius:8px}label{display:block;margin:15px 0;font-size:14px}a{color:#ead298}small{color:#bdb29c}footer{border-top:1px solid #4d4738}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">HALCYON / DOJO DE LEDIAN / SOUS-SOL</div><h1>Trois couloirs · trois salles vides</h1><p>Roche brun-gris, dalles irrégulières et chemin en terre ocre, d’après la vraie carte de Palika. Variantes générées puis corrigées et découpées en calques. Aucun mobilier ni personnage ajouté.</p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma des accès</button><button id="reference">Voir référence native</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><p id="status"></p></section><aside><b>Calques alignés · 512 × 512</b><div id="layers"></div><small>Les raccords de sol sont indépendants. L’échelle native est disponible sur la salle latérale et désactivée par défaut. Les murs/rochers sont des partitions visibles, pas des volumes reconstruits derrière les autres calques.</small></aside></div></main><footer><p>Source : Palikadude/Halcyon, ledian_dojo.rsground, reconstruite depuis ses sept banques de tuiles. Les architectures sont des générations guidées, pas six cartes natives originales. Le patch des raccords et l’échelle proviennent directement des pixels sources.</p><small>15 ports de64px : sol opaque et bande de jonction commune vérifiés. Cela ne valide ni les collisions, ni le raccord de toute la silhouette rocheuse, ni les transitions PMDO. Rendus statiques, sans animation de décor.</small></footer><script>const DATA=__DATA__,REF=__REF__,c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let entry,images={},visible={},schema=false,reference=false;function image(src){let im=new Image();im.src=src;return im}const ref=image(REF);function download(src,name){let a=document.createElement('a');a.href=src;a.download=name;a.click()}for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}select.value='salle_traversee';function setup(){entry=DATA[select.value];images={};visible={};const root=document.getElementById('layers');root.innerHTML='';for(const n of entry.layers){images[n]=image(entry.images[n]);visible[n]=!entry.optional.includes(n);const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=visible[n];ch.onchange=()=>visible[n]=ch.checked;a.href=entry.images[n];a.download=entry.id+'_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(n.replace(/^\d+_/,'').replaceAll('_',' ')),a);root.append(l)}images.schema=image(entry.schema);document.getElementById('status').textContent=entry.title+' · Accès : '+entry.ports.map(p=>p.direction).join(' / ')+' · largeur de raccord64px'}select.onchange=setup;document.getElementById('plan').onclick=e=>{schema=!schema;reference=false;e.target.textContent=schema?'Voir rendu':'Voir schéma des accès'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Revenir à la variante':'Voir référence native'};document.getElementById('export').onclick=()=>download(c.toDataURL(),reference?'ledian_reference.png':entry.id+(schema?'_schema':'')+'.png');function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function render(){const w=reference?408:512,h=reference?312:512;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else for(const n of entry.layers)if(visible[n])draw(images[n]);requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R/'apercu_ledian_dojo_v1.html').write_text(h.replace('__DATA__',json.dumps(data)).replace('__REF__',json.dumps(uri(R/'source/ledian_dojo_v1/references/ledian_dojo_reference.png'))),encoding='utf8')
